//! `ImageryLayer.fromProviderAsync` readiness and errors, and
//! `ImageryLayerCollection` provider-ready forwarding, against the pinned
//! CesiumJS traces in `tests/data/scene-imagery-layer-providers.json`
//! (generated by `tools/cesium/generate-scene-imagery-layer-providers.mjs`).
#![allow(clippy::arc_with_non_send_sync)] // Providers use single-threaded shared state.

use cesium_rs::core::*;
use cesium_rs::scene::imagery_provider::{ImageryErrorEvent, ImageryFuture, ImageryProvider};
use cesium_rs::scene::*;
use serde_json::{json, Value};
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};

struct NamedProvider {
    scheme: GeographicTilingScheme,
    error_event: ImageryErrorEvent,
}

impl ImageryProvider for NamedProvider {
    fn rectangle(&self) -> &Rectangle {
        self.scheme.rectangle()
    }
    fn tile_width(&self) -> f64 {
        256.0
    }
    fn tile_height(&self) -> f64 {
        256.0
    }
    fn maximum_level(&self) -> Option<u32> {
        None
    }
    fn tiling_scheme(&self) -> &dyn TilingScheme {
        &self.scheme
    }
    fn error_event(&self) -> &ImageryErrorEvent {
        &self.error_event
    }
    fn request_image(&self, _: i32, _: i32, _: u32) -> Option<ImageryFuture> {
        None
    }
}

/// A provider promise the script resolves or rejects.
type Settlement = Rc<RefCell<Option<Result<Arc<dyn ImageryProvider>, RuntimeError>>>>;

fn deferred() -> (Settlement, impl std::future::Future<Output = Result<Arc<dyn ImageryProvider>, RuntimeError>>) {
    let slot: Settlement = Rc::new(RefCell::new(None));
    let reader = slot.clone();
    (
        slot,
        std::future::poll_fn(move |_| match reader.borrow_mut().take() {
            Some(result) => Poll::Ready(result),
            None => Poll::Pending,
        }),
    )
}

fn provider_key(provider: &Arc<dyn ImageryProvider>) -> usize {
    Arc::as_ptr(provider) as *const () as usize
}

#[test]
fn provider_readiness_and_forwarding_match_reference() {
    let fixture: Value = serde_json::from_str(include_str!("data/scene-imagery-layer-providers.json")).unwrap();
    let waker = Waker::noop();
    let mut cx = Context::from_waker(waker);
    for scenario in fixture["scenarios"].as_array().unwrap() {
        let name = scenario["name"].as_str().unwrap();
        let log: Arc<Mutex<Vec<Value>>> = Arc::default();
        let mut collection = ImageryLayerCollection::new();
        // Layer ids and provider pointers stand in for names inside listeners.
        let names: Arc<Mutex<HashMap<u64, String>>> = Arc::default();
        let provider_names: Arc<Mutex<HashMap<usize, String>>> = Arc::default();
        let name_of = |names: &Arc<Mutex<HashMap<u64, String>>>, id: u64| names.lock().unwrap()[&id].clone();
        {
            let (l, n) = (log.clone(), names.clone());
            collection.layer_added.add_event_listener(move |e| {
                let id = e.layer.borrow().id();
                l.lock().unwrap().push(json!(["layerAdded", name_of(&n, id), e.index]));
            });
            let (l, n) = (log.clone(), names.clone());
            collection.layer_removed.add_event_listener(move |e| {
                let id = e.layer.borrow().id();
                l.lock().unwrap().push(json!(["layerRemoved", name_of(&n, id), e.index]));
            });
            let (l, n) = (log.clone(), names.clone());
            collection.layer_moved.add_event_listener(move |e| {
                let id = e.layer.borrow().id();
                l.lock().unwrap().push(json!(["layerMoved", name_of(&n, id), e.new_index, e.old_index]));
            });
            let (l, n) = (log.clone(), names.clone());
            collection.layer_shown_or_hidden.add_event_listener(move |e| {
                let id = e.layer.borrow().id();
                l.lock().unwrap().push(json!(["layerShownOrHidden", name_of(&n, id), e.index, e.show]));
            });
        }

        let mut layers: Vec<(String, ImageryLayerHandle, Settlement)> = Vec::new();
        let find = |layers: &Vec<(String, ImageryLayerHandle, Settlement)>, l: &str| {
            layers.iter().find(|(n, ..)| n == l).map(|(_, h, s)| (h.clone(), s.clone())).unwrap()
        };
        for (i, step) in scenario["steps"].as_array().unwrap().iter().enumerate() {
            let op = step["op"].as_str().unwrap();
            let args = step["args"].as_array().unwrap();
            let arg = |k: usize| args[k].as_str().unwrap().to_string();
            let before = log.lock().unwrap().len();
            match op {
                "make" => {
                    let layer_name = arg(0);
                    let options = args.get(1).filter(|v| !v.is_null());
                    let listen = args.get(2).filter(|v| !v.is_null());
                    let (slot, future) = deferred();
                    let mut layer = ImageryLayer::from_provider_async(
                        future,
                        ImageryLayerOptions { show: options.and_then(|o| o["show"].as_bool()), ..Default::default() },
                    );
                    names.lock().unwrap().insert(layer.id(), layer_name.clone());
                    if listen.is_none_or(|l| l["ready"].as_bool().unwrap()) {
                        let (l, p, n) = (log.clone(), provider_names.clone(), layer_name.clone());
                        layer.ready_event.add_event_listener(move |provider| {
                            let provider = p.lock().unwrap()[&provider_key(provider)].clone();
                            l.lock().unwrap().push(json!(["readyEvent", n, provider]));
                        });
                    }
                    if listen.is_none_or(|l| l["error"].as_bool().unwrap()) {
                        let (l, n) = (log.clone(), layer_name.clone());
                        layer.error_event.add_event_listener(move |e| {
                            l.lock().unwrap().push(json!(["errorEvent", n, e.message]));
                        });
                    }
                    layers.push((layer_name, layer.into_handle(), slot));
                }
                "add" => {
                    let index = args.get(1).and_then(Value::as_u64).map(|v| v as usize);
                    collection.add(find(&layers, &arg(0)).0, index).unwrap();
                }
                "remove" => {
                    assert!(collection.remove(&find(&layers, &arg(0)).0, args[1].as_bool()));
                }
                "raise" => collection.raise(&find(&layers, &arg(0)).0).unwrap(),
                "lowerToBottom" => collection.lower_to_bottom(&find(&layers, &arg(0)).0).unwrap(),
                "destroy" => find(&layers, &arg(0)).0.borrow_mut().destroy().unwrap(),
                "resolve" => {
                    let layer_name = arg(0);
                    let provider: Arc<dyn ImageryProvider> = Arc::new(NamedProvider {
                        scheme: GeographicTilingScheme::default(),
                        error_event: Rc::new(RefCell::new(MutableErrorEvent::new())),
                    });
                    provider_names.lock().unwrap().insert(provider_key(&provider), format!("provider-{layer_name}"));
                    *find(&layers, &layer_name).1.borrow_mut() = Some(Ok(provider));
                }
                "reject" => {
                    let layer_name = arg(0);
                    *find(&layers, &layer_name).1.borrow_mut() =
                        Some(Err(RuntimeError::new(format!("failed {layer_name}"))));
                }
                other => panic!("unknown op {other}"),
            }
            // Cesium's `await flush()`: settle every promise, then forward.
            for (_, layer, _) in &layers {
                let _ = layer.borrow_mut().poll_provider(&mut cx);
            }
            collection.poll_providers(&mut cx);

            let context = format!("{name} step {i} {op} {args:?}");
            let mut expected_events: Vec<Value> = step["events"].as_array().unwrap().clone();
            // Without an errorEvent listener Cesium logs to the console; the
            // port logs to standard error, which this test does not capture.
            expected_events.retain(|e| e[0] != "consoleError");
            assert_eq!(log.lock().unwrap()[before..].to_vec(), expected_events, "{context}");

            for (layer_name, layer, _) in &layers {
                let expected = &step["state"][layer_name];
                let l = layer.borrow();
                let destroyed = l.is_destroyed();
                assert_eq!(json!(destroyed), expected["destroyed"], "{context} {layer_name} destroyed");
                assert_eq!(json!(l.layer_index()), expected["index"], "{context} {layer_name} index");
                if !destroyed {
                    assert_eq!(json!(l.ready()), expected["ready"], "{context} {layer_name} ready");
                    let provider =
                        l.imagery_provider().map(|p| provider_names.lock().unwrap()[&provider_key(p)].clone());
                    assert_eq!(json!(provider), expected["provider"], "{context} {layer_name} provider");
                }
            }
            let order: Vec<String> =
                collection.layers().iter().map(|h| names.lock().unwrap()[&h.borrow().id()].clone()).collect();
            assert_eq!(json!(order), step["order"], "{context} order");
        }
    }
}
